// agent-ledger plugin for Amp (CLI plugin API). agent-ledger-plugin:amp
// Generated by `agent-ledger init --agent amp`. Do not edit: re-run init instead.
// Plain JavaScript in a .ts file, so it needs no build step.
//
// Every tool call is sent to agent-ledger before it runs. "deny" rejects the call and the model sees
// the reason. Amp has no "ask" result, so "ask" opens Amp's own confirmation (ctx.ui.confirm); with no
// way to ask, the call is rejected as needing human approval. Results are recorded too. Recording
// never throws.
import { spawn } from "node:child_process"

const HOOK = __HOOK_ARGV__
const FAIL_CLOSED = __FAIL_CLOSED__
const TIMEOUT_MS = 10000

function call(payload) {
  return new Promise((resolve) => {
    let child
    try {
      child = spawn(HOOK[0], HOOK.slice(1), { stdio: ["pipe", "pipe", "pipe"] })
    } catch (e) {
      resolve({ failed: `cannot start agent-ledger: ${e.message}` })
      return
    }
    let out = ""
    let err = ""
    let done = false
    const finish = (value) => {
      if (!done) {
        done = true
        clearTimeout(timer)
        resolve(value)
      }
    }
    const timer = setTimeout(() => {
      child.kill("SIGKILL")
      finish({ failed: "agent-ledger timed out" })
    }, TIMEOUT_MS)
    child.stdout.on("data", (d) => (out += d))
    child.stderr.on("data", (d) => (err += d))
    child.on("error", (e) => finish({ failed: `cannot start agent-ledger: ${e.message}` }))
    child.on("close", (code) => {
      if (code === 2) return finish({ failed: err.trim() || "agent-ledger failed (fail-closed)", closed: true })
      if (!out.trim()) return finish({})
      try {
        finish(JSON.parse(out))
      } catch {
        finish({ failed: "agent-ledger returned invalid output" })
      }
    })
    child.stdin.on("error", () => {})
    child.stdin.end(JSON.stringify(payload))
  })
}

function root(amp) {
  const r = amp?.system?.workspaceRoot
  const s = r === undefined || r === null ? "" : String(r?.fsPath || r)
  return s.startsWith("file://") ? decodeURIComponent(s.slice(7)) : s || undefined
}

function shellOf(amp, e) {
  try {
    const s = amp?.helpers?.shellCommandFromToolCall?.(e)
    return s && typeof s.command === "string" ? { command: s.command, dir: s.dir ? String(s.dir) : undefined } : undefined
  } catch {
    return undefined
  }
}

const reject = (message) => ({ action: "reject-and-continue", message })

export default function agentLedger(amp) {
  amp.on("tool.call", async (e, ctx) => {
    const res = await call({ agent: "amp", phase: "tool.before", tool: e?.tool, args: e?.input, shell: shellOf(amp, e),
                             sessionID: e?.thread?.id, callID: e?.toolUseID, directory: root(amp) })
    if (res.failed) return FAIL_CLOSED || res.closed ? reject(`agent-ledger: ${res.failed}`) : { action: "allow" }
    if (res.decision === "deny") return reject(res.reason || "agent-ledger: blocked by policy")
    if (res.decision === "ask") {
      const reason = res.reason || "agent-ledger: needs approval"
      try {
        if (ctx?.ui?.confirm && (await ctx.ui.confirm(`${reason}\n\nAllow ${e?.tool}?`))) return { action: "allow" }
      } catch {
        // no usable prompt: fall through to a rejection
      }
      return reject(`${reason} - this needs human approval and was not approved, so it was not run.`)
    }
    return { action: "allow" }
  })

  amp.on("tool.result", async (e) => {
    try {
      const failed = e?.status === "error" || e?.status === "cancelled"
      await call({ agent: "amp", phase: failed ? "tool.error" : "tool.after", tool: e?.tool, args: e?.input,
                   shell: shellOf(amp, e), sessionID: e?.thread?.id, callID: e?.toolUseID, directory: root(amp),
                   output: failed ? undefined : e?.output, error: failed ? String(e?.error || e?.status) : undefined })
    } catch {
      // recording must never break the session
    }
  })
}
